package com.village.controller;
import com.village.model.Family; import com.village.repository.FamilyRepository; import jakarta.validation.Valid; import org.springframework.data.domain.Sort; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.GrantedAuthority; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api") public class FamilyController{
 private final FamilyRepository repo; private final com.village.repository.UserRepository users; public FamilyController(FamilyRepository r,com.village.repository.UserRepository u){repo=r;users=u;}
 private boolean admin(Authentication a){return a.getAuthorities().stream().map(GrantedAuthority::getAuthority).anyMatch("ROLE_ADMIN"::equals);}
 private Long userId(Authentication a){return users.findByUsername(a.getName()).map(com.village.model.VillageUser::getId).orElse(null);}
 @GetMapping("/families") public List<Family> list(@RequestParam(required=false) String q,Authentication a){
   if(admin(a)) return (q==null||q.isBlank())?repo.findAll(Sort.by("familyId")):repo.search(q.trim());
   var f=repo.findByUserId(userId(a)); if(q!=null&&!q.isBlank()) f=f.stream().filter(x->(x.getFamilyId()+x.getHouseNumber()+x.getHeadName()+x.getOccupation()).toLowerCase().contains(q.toLowerCase())).toList(); return f;
 }
 @GetMapping("/families/{id}") public Family get(@PathVariable Long id,Authentication a){Family f=find(id); if(!admin(a)&&!Objects.equals(f.getUserId(),userId(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Access denied"); return f;}
 @PostMapping("/families") @ResponseStatus(HttpStatus.CREATED) public Family create(@Valid @RequestBody Family f,Authentication a){if(!admin(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only admin can create standalone families"); f.setId(null); if(repo.existsByFamilyId(f.getFamilyId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Family ID already exists"); f.setStatus("APPROVED"); return repo.save(f);}
 @PutMapping("/families/{id}") public Family update(@PathVariable Long id,@Valid @RequestBody Family in,Authentication a){Family old=find(id);if(!admin(a)&&!Objects.equals(old.getUserId(),userId(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Access denied");if(repo.existsByFamilyIdAndIdNot(in.getFamilyId(),id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Family ID already exists");in.setId(id);in.setUserId(old.getUserId()); if(!admin(a)){in.setFamilyId(old.getFamilyId());in.setStatus("PENDING");in.setRejectionReason(null);} return repo.save(in);}
 @DeleteMapping("/families/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){Family f=find(id);if(!admin(a)&&(!Objects.equals(f.getUserId(),userId(a))||"APPROVED".equals(f.getStatus())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only admin can delete an approved family");repo.delete(f);}
 @PutMapping("/families/{id}/decision") public Family decision(@PathVariable Long id,@RequestBody Map<String,String> body,Authentication a){if(!admin(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin only");Family f=find(id);String status=body.get("status");if(!List.of("APPROVED","REJECTED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid decision");f.setStatus(status);f.setRejectionReason("REJECTED".equals(status)?body.getOrDefault("reason",""):null); return repo.save(f);}
 @GetMapping("/stats") public Map<String,Object> stats(Authentication a){var s=repo.stats(); Map<String,Object> out=new LinkedHashMap<>(); out.put("totalFamilies",s.getTotalFamilies());out.put("totalMembers",s.getTotalMembers());out.put("male",s.getMale());out.put("female",s.getFemale());out.put("children",s.getChildren());out.put("pending",repo.countByStatus("PENDING"));out.put("approved",repo.countByStatus("APPROVED"));out.put("rejected",repo.countByStatus("REJECTED"));if(!admin(a)){var mine=repo.findByUserId(userId(a));out.put("myFamily",mine.isEmpty()?null:mine.get(0));}return out;}
 private Family find(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Family not found"));}
}
